--DS d_pick_ticket_oe_lines
SELECT	oe_line.order_no,oe_line.line_no,inv_mast.item_id,oe_line.qty_allocated,oe_line.unit_of_measure,oe_line.unit_size,oe_line.qty_ordered,oe_line.qty_on_pick_tickets,oe_line.ship_loc_id,oe_line.will_call,oe_line.qty_invoiced,oe_line.default_in_oe,oe_line.other_charge,oe_line.extended_price,oe_line.company_no,oe_hdr.order_date,oe_hdr.address_id,oe_line.qty_canceled,oe_line.tax_item,oe_line.qty_staged,' ' pick_and_hold,oe_line.scheduled,oe_line.source_loc_id,' ' auxiliary,oe_line.disposition,' ' current_is_ship_loc,0.000000000 qty_on_auxiliary,oe_line.assembly,oe_line.oe_line_uid,oe_line.parent_oe_line_uid,oe_line.qty_per_assembly,inv_mast.serialized,inv_mast.track_lots,oe_line.detail_type,oe_line.freight_in,oe_line.inv_mast_uid,oe_line.lot_bill,inv_loc.default_shipment,CASE oe_line.lot_billWHEN 'Y' THEN CASE oe_line.detail_typeWHEN 0 THEN 'Y'ELSE 'N'ENDELSE 'N'END c_nested_lot_bill_hdr,oe_line.sales_cost,oe_line.pricing_unit_size,oe_line_service.oe_line_service_uid,oe_line_service_part.oe_line_service_uid parent_oe_line_service_uid,oe_line_service.row_status_flag,oe_line_service_parent.parts_packing_basis,oe_line.item_bill_to_id, revision_transaction.item_revision_uid,oe_line.dea_restriction_failed,oe_line.original_freight_in,COALESCE(customer_terms_item.terms_id, COALESCE(customer_terms_pg.terms_id, oe_hdr.terms)) terms_id,COALESCE(oe_line.complete, 'N') oe_line_complete,COALESCE(peer_oe_line_uid, 0),oe_line.routing_status_flag,oe_hdr.customer_id,oe_hdr.location_id sales_location_id,inv_mast.product_type,'' pick_ticket_group_no,'Y' create_pick_ticket_line_flag,oe_hdr.po_no,oe_line.supplier_id,oe_line.job_price_bin_uid,oe_line.rental_flag FROM oe_lineINNER JOIN oe_hdr ON oe_hdr.order_no = oe_line.order_noINNER JOIN inv_mast ON inv_mast.inv_mast_uid = oe_line.inv_mast_uidINNER JOIN inv_loc ON inv_loc.inv_mast_uid = oe_line.inv_mast_uid ANDinv_loc.location_id = oe_hdr.location_idLEFT JOIN tag_hold_class ON oe_line.tag_hold_class_uid = tag_hold_class.tag_hold_class_uidLEFT JOIN oe_line_service ON oe_line_service.oe_line_uid = oe_line.oe_line_uid ANDoe_hdr.order_type = 1706LEFT JOIN oe_line_service_part ON oe_line_service_part.oe_line_uid = oe_line.oe_line_uid ANDoe_hdr.order_type = 1706LEFT JOIN oe_line_service AS oe_line_service_parent ON oe_line_service_parent.oe_line_service_uid = oe_line_service_part.oe_line_service_uid ANDoe_hdr.order_type = 1706LEFT JOIN revision_transaction ON revision_transaction.transaction_no = cast(oe_line.order_no as int)AND revision_transaction.transaction_line_no = oe_line.line_noAND revision_transaction.transaction_code_no IN (1533, 1721)LEFT JOIN product_group ON (product_group.company_id = oe_hdr.company_id) AND(product_group.product_group_id = oe_line.product_group_id)LEFT JOIN customer_terms AS customer_terms_item ON (customer_terms_item.company_id = oe_hdr.company_id) AND(customer_terms_item.customer_id = oe_hdr.customer_id) AND(customer_terms_item.type_uid = oe_line.inv_mast_uid) AND(customer_terms_item.type_no = 212) AND(customer_terms_item.row_status_flag = 704)LEFT JOIN customer_terms AS customer_terms_pg ON (customer_terms_pg.company_id = oe_hdr.company_id) AND(customer_terms_pg.customer_id = oe_hdr.customer_id) AND(customer_terms_pg.type_uid = product_group.product_group_uid) AND(customer_terms_pg.type_no = 218) AND(customer_terms_pg.row_status_flag = 704)WHERE oe_line.order_no = '1092768' ANDoe_line.cancel_flag = 'N' AND( ( oe_hdr.order_type = 1706 AND( oe_line_service.row_status_flag = 1268 OR ( oe_line_service.oe_line_service_uid IS NOT NULL ANDoe_line_service.row_status_flag IN (1732, 1733) ANDEXISTS ( SELECT oe_line_b.order_noFROM oe_line oe_line_bINNER JOIN oe_line_service_part oe_line_service_part_b ON oe_line_b.oe_line_uid = oe_line_service_part_b.oe_line_uidWHERE oe_line_service.oe_line_service_uid = oe_line_service_part_b.oe_line_service_uid ANDoe_line_b.qty_ordered - oe_line_b.qty_canceled > 0 ANDoe_line_b.qty_allocated + oe_line_b.qty_staged > 0 ANDoe_line_b.required_date BETWEEN {ts '1990-01-01 00:00:00.000'} AND {ts '2020-09-10 23:59:59.000'} ) ) ) ) OR( ( ( oe_line.qty_ordered - oe_line.qty_canceled > 0 AND( oe_line.qty_allocated + oe_line.qty_staged > 0 ORoe_line.lot_bill = 'Y' ORoe_line.detail_type = 1 ) ) OR( oe_hdr.rma_flag = 'N' ANDoe_line.parent_oe_line_uid > 0 ANDqty_per_assembly < 0 ANDqty_ordered < 0 ) ) AND( oe_line.ship_loc_id = 300 OR( oe_line.source_loc_id = 300 ANDoe_line.source_loc_id <> oe_line.ship_loc_id ) OR( oe_line.lot_bill = 'Y' ) ) AND( EXISTS (SELECT * FROM oe_line AS oe_line_cWHERE oe_line_c.order_no = '1092768' AND( oe_line_c.parent_oe_line_uid = 0 OR( oe_line_c.parent_oe_line_uid <> 0 ANDoe_line_c.qty_per_assembly <> 0 ) ORoe_line_c.detail_type = 3 ) AND( oe_line_c.qty_allocated > 0 OR( ( oe_line_c.disposition = 'C' ANDoe_hdr.packing_basis <> 'Partial' ) ORoe_line_c.qty_staged > 0 ) OR( 'N' = 'Y' ANDoe_line_c.qty_staged > 0 ) ) AND( oe_line_c.ship_loc_id = 300 OR( oe_line_c.source_loc_id = 300 ANDoe_line_c.source_loc_id <> oe_line_c.ship_loc_id ) ) AND( oe_line_c.default_in_oe = 'N' ORoe_line_c.other_charge = 'N' ) ) ) AND( ( oe_line.scheduled = 'N' AND ( ( oe_line.required_date BETWEEN {ts '1990-01-01 00:00:00.000'} AND {ts '2020-09-10 23:59:59.000'} OR( oe_line.required_date < {ts '2020-09-10 23:59:59.000'} AND oe_hdr.packing_basis NOT IN ('Item Complete', 'Partial') ) ) OR oe_line.lot_bill = 'Y') ) OREXISTS ( SELECT *FROM oe_line_scheduleWHERE oe_line_schedule.order_no = oe_line.order_no ANDoe_line_schedule.line_no = oe_line.line_no ANDoe_line_schedule.allocated_qty + oe_line_schedule.qty_staged <> 0 AND((oe_line_schedule.pick_date <= {ts '2020-09-03 09:37:39.000'}) OR (oe_line_schedule.pick_date <= {ts '2020-09-10 23:59:59.000'} AND 'N' = 'Y') ) ) ) AND( oe_hdr.order_type <> 1706 ORoe_hdr.order_type IS NULL OR(oe_line_service_part.oe_line_service_uid IS NOT NULLAND oe_line_service_parent.row_status_flag IN (1732, 1733)) ) ) )AND (COALESCE(oe_line.rental_flag,'N') = 'N' OR ((oe_line.rental_flag = 'Y') AND (oe_hdr.rental_transaction_status_cd = 222 OR oe_hdr.rental_transaction_status_cd = 60010 OR oe_hdr.rental_transaction_status_cd = 947)))AND oe_line.complete = 'N'	AND ('N' = 'N' OR oe_line.scheduled = 'Y' OR COALESCE(oe_line.pick_date, {ts '1900-01-01 00:00:00.000'}) BETWEEN {ts '1900-01-01 00:00:00.000'} AND {ts '1900-01-01 00:00:00.000'} OR ( COALESCE(oe_line.pick_date, {ts '1900-01-01 00:00:00.000'}) < {ts '1900-01-01 00:00:00.000'} AND oe_hdr.packing_basis NOT IN ('Item Complete', 'Partial') ) )ORDER BY oe_line.line_no